const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const body = $input.first().json.body;
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const timestamp = Number(headers['x-hitl-timestamp']);
const sig = String(headers['x-signature-256'] || '');
if (!timestamp || Math.abs(Math.floor(Date.now() / 1000) - timestamp) > 300) {
  throw new Error('Expired or missing X-HITL-Timestamp');
}
const secrets = [$env.HITL_WEBHOOK_SECRET, $env.HITL_WEBHOOK_SECRET_PREV].filter(Boolean);
const valid = secrets.some((secret) => {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
});
if (!valid) throw new Error('Invalid HMAC signature');
return [{ json: typeof body === 'string' ? JSON.parse(body) : body }];
